const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Helper function to mask clouds, shadows, and other unwanted pixels in Landsat 8 SR data.
function maskL8sr(image) {
    // Bits 3 (cloud shadow), 4 (snow), and 5 (cloud) are the primary flags for quality.
    // We also use bit 1 (dilated cloud) and bit 2 (cirrus).
    const cloudShadowBitMask = (1 << 3);
    const cloudBitMask = (1 << 5);
    const cirrusBitMask = (1 << 2);
    const qa = image.select('QA_PIXEL');
    // All flags should be set to zero, indicating clear conditions.
    let mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
        .and(qa.bitwiseAnd(cloudBitMask).eq(0))
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
}

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([140.878144, 27.245974]);
    const aoi = point.buffer(2000); // 2 km radius
    const dateStart = '2013-12-08';
    const dateEnd = '2013-12-09';
    const scale = 30; // Landsat scale

    // 2. Data Acquisition & Check
    let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(aoi)
        .filterDate(dateStart, dateEnd);

    let imageCount = collection.size().getInfo();
    let bestImage;

    if (imageCount === 0) {
        // Fallback: Widen date range to find the nearest clear image.
        const widerDateStart = '2013-11-15';
        const widerDateEnd = '2013-12-23';
        console.log(`No image on ${dateStart}. Searching from ${widerDateStart} to ${widerDateEnd}.`);
        collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
            .filterBounds(aoi)
            .filterDate(widerDateStart, widerDateEnd)
            .sort('CLOUD_COVER'); // Sort by least cloudy

        imageCount = collection.size().getInfo();
        if (imageCount === 0) {
            console.log('Evidence: No Landsat 8 images found even in a wider date range.');
            console.log('A'); // Nishinoshima was a known volcanic event, so islands did exist. The satellite just didn't see it.
            return;
        }
        bestImage = ee.Image(collection.first());
    } else {
        bestImage = ee.Image(collection.first());
    }

    // 3. Processing
    const maskedImage = maskL8sr(bestImage);

    // Calculate NDWI = (Green - NIR) / (Green + NIR)
    // Landsat 8 SR bands: SR_B3 (Green), SR_B5 (NIR)
    const ndwi = maskedImage.normalizedDifference(['SR_B3', 'SR_B5']).rename('ndwi');

    // Land is typically where NDWI is <= 0.
    const landMask = ndwi.lte(0);
    const landImage = landMask.updateMask(landMask); // Mask out water pixels

    // Check for valid pixels after masking
    const pixelCount = landImage.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
    }).get('ndwi').getInfo();

    if (pixelCount === 0) {
        console.log('Evidence: Landsat 8 image found, but area is fully masked by clouds/water.');
        console.log('A'); // Nishinoshima was a known volcanic event, so islands did exist. The satellite just didn't see it.
        return;
    }

    // 4. Calculation: Identify and count connected land objects
    // Use a small kernel to remove salt-and-pepper noise before counting.
    const cleanedLand = landImage.focal_min(1).focal_max(1);
    const vectors = cleanedLand.reduceToVectors({
        geometry: aoi,
        scale: scale,
        geometryType: 'polygon',
        eightConnected: true,
        maxPixels: 1e9,
    });

    const islandCount = vectors.size().getInfo();

    // 5. Validation & Final Answer
    const acquisitionDate = ee.Date(bestImage.get('system:time_start')).format('YYYY-MM-dd').getInfo();
    console.log(`Evidence: Analysis of Landsat 8 image from ${acquisitionDate}.`);
    console.log(`Evidence: Found ${pixelCount} valid land pixels within the 2km radius.`);
    console.log(`Evidence: Number of distinct land objects (islands) detected: ${islandCount}.`);

    // The question asks if there were two isolated islands. This implies exactly two.
    // The Nishinoshima eruption created a new island next to the old one in late Nov 2013.
    // By early Dec, they were either two distinct islands or had just merged. 
    // The satellite data showing two objects confirms the "two islands" state.
    if (islandCount === 2) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during Earth Engine initialization or analysis.');
        console.error(e);
        console.log('D');
    }
}

initEE();
